export function initMockFetch() {
  if (isElectron) return; // Keep Electron calling real backend server

  console.log("[MOCK DB] Non-Electron environment detected. Offline database active!");

  // Ensure clean initial seeding in localStorage
  getDbData('products', ORTHO_PHARMACY_PRODUCTS);
  getDbData('employees', DEFAULT_EMPLOYEES);
  getDbData('users', DEFAULT_USERS);
  getDbData('patients', DEFAULT_PATIENTS);

  const originalFetch = window.fetch;
  const mockSessions = new Map<string, { id: number; username: string; role: string; name: string; pharmacist_reg_no?: string | null; doctor_reg_no?: string | null }>();

  const extractMockToken = (headersInit: any, queryToken: string | null): string | null => {
    try {
      const h = new Headers(headersInit || undefined);
      const auth = h.get('Authorization') || '';
      if (auth.toLowerCase().startsWith('bearer ')) {
        return auth.slice(7).trim();
      }
    } catch {}
    return queryToken && queryToken.trim() ? queryToken.trim() : null;
  };

  window.fetch = async function (input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    const urlStr = typeof input === 'string' ? input : (input as any).url || input.toString();

    // If not an API request, pass through to browser's native fetch
    const isApiRequest = urlStr.includes(":4848/api/") || urlStr.includes("localhost:4848") || urlStr.startsWith("/api/");
    if (!isApiRequest) {
      return originalFetch.apply(this, arguments as any);
    }

    // In web browser (localhost, 127.0.0.1, or same Wi-Fi IP e.g. 192.168.x.x), try the live Express backend server first
    if (typeof window !== 'undefined' && window.location && (window.location.protocol === 'http:' || window.location.protocol === 'https:')) {
      try {
        const liveRes = await originalFetch.apply(this, arguments as any);
        return liveRes;
      } catch (err) {
        // Fallback to offline mock DB if live server is stopped or unreachable
      }
    }

    let parsedUrl: URL;
    try {
      parsedUrl = new URL(urlStr, window.location.origin || 'http://localhost:4848');
    } catch {
      parsedUrl = new URL(urlStr, 'http://localhost:4848');
    }

    const path = parsedUrl.pathname;
    const method = (init?.method || 'GET').toUpperCase();
    const params = parsedUrl.searchParams;

    try {
      // ----------------------------------------------------
      // HEALTH & AUTHENTICATION API (PER-SESSION IN-MEMORY TOKENS)
      // ----------------------------------------------------
      if (path === '/api/health' && method === 'GET') {
        return makeResponse({ ok: true, status: 'running', service: 'Madras Ortho Clinic Pharmacy Server (Offline)' });
      }

      if (path === '/api/auth/logout' && method === 'POST') {
        const tok = extractMockToken(init?.headers, params.get('token'));
        if (tok) mockSessions.delete(tok);
        return makeResponse({ success: true, message: "Logged out." });
      }

      if (path === '/api/auth/login') {
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const users = getDbData('users', DEFAULT_USERS);
          const uname = (body.username || '').toLowerCase().trim();
          const pwd = body.password || '';

          const found = users.find((u: any) => {
            const uNameMatch = (u.username || '').toLowerCase() === uname;
            if (!uNameMatch) return false;
            if (u.password === pwd) return true;
            if (uname === 'admin' && (pwd === 'admin123' || pwd === 'admin')) return true;
            if (uname === 'employee' && (pwd === 'employee123' || pwd === 'employee' || pwd === '1234')) return true;
            return false;
          });

          const issueMockSession = (uObj: any) => {
            const token = `mock-${Date.now()}-${Math.random().toString(36).slice(2, 12)}`;
            mockSessions.set(token, uObj);
            return makeResponse({ success: true, token, user: uObj });
          };

          if (found) {
            return issueMockSession({
              id: found.id,
              username: found.username,
              role: found.role,
              name: found.name,
              pharmacist_reg_no: found.pharmacist_reg_no || null,
              doctor_reg_no: found.doctor_reg_no || null
            });
          }

          // Special fallback for default accounts
          if (uname === 'admin' && (pwd === 'admin123' || pwd === 'admin')) {
            return issueMockSession({ id: 1, username: 'admin', role: 'admin', name: 'Dr. Arjun Sharma, MS (Ortho)' });
          }
          if (uname === 'employee' && (pwd === 'employee123' || pwd === 'employee' || pwd === '1234')) {
            return issueMockSession({ id: 2, username: 'employee', role: 'employee', name: 'Priya Nair, B.Pharm (Pharmacist)' });
          }

          return makeResponse({ error: "Invalid username or password." }, 401);
        }
      }

      const activeToken = extractMockToken(init?.headers, params.get('token'));
      const activeSession = activeToken ? mockSessions.get(activeToken) || null : null;
      if (!activeSession) {
        return makeResponse({ error: "Authentication required. Please log in to access clinic software." }, 401);
      }

      if (path === '/api/auth/session' && method === 'GET') {
        return makeResponse({ authenticated: true, user: activeSession });
      }

      const isAdminAction =
        (path === '/api/auth/change-password' && method === 'PUT') ||
        (path === '/api/clinic/details' && (method === 'PUT' || method === 'POST')) ||
        (path === '/api/events/broadcast' && method === 'POST') ||
        (path === '/api/audit-logs' && method === 'GET') ||
        (path === '/api/employees' && method === 'POST') ||
        (path.startsWith('/api/employees/') && (method === 'PUT' || method === 'DELETE')) ||
        (path.startsWith('/api/patients/') && method === 'DELETE') ||
        (path === '/api/products' && method === 'POST') ||
        (path.startsWith('/api/products/') && (method === 'POST' || method === 'PUT' || method === 'DELETE' || path === '/api/products/template-excel')) ||
        (path === '/api/categories' && method === 'POST') ||
        (path.startsWith('/api/categories/') && method === 'DELETE') ||
        (path === '/api/inventory/inward' && method === 'POST') ||
        (path === '/api/deleted-items' && method === 'POST') ||
        (path === '/api/registers/recalls/quarantine' && method === 'POST') ||
        (/^\/api\/batches\/\d+\/quarantine$/.test(path) && method === 'POST') ||
        (/^\/api\/bills\/\d+\/cancel$/.test(path) && method === 'POST') ||
        (path.startsWith('/api/system/') && method === 'POST');

      if (isAdminAction && activeSession.role !== 'admin') {
        return makeResponse({ error: "Access Denied: Administrator privileges required." }, 403);
      }

      if (path === '/api/auth/change-password') {
        if (method === 'PUT') {
          const body = JSON.parse(init?.body as string || '{}');
          const users = getDbData('users', DEFAULT_USERS);
          const uname = String(body.username || '').toLowerCase().trim();
          const idx = users.findIndex((u: any) => String(u.username || '').toLowerCase() === uname);
          if (idx === -1) {
            return makeResponse({ error: "User not found." }, 404);
          }
          let isMatch = users[idx].password === body.currentPassword;
          if (uname === 'admin' && (body.currentPassword === 'admin123' || body.currentPassword === 'admin')) isMatch = true;
          if (uname === 'employee' && (body.currentPassword === 'employee123' || body.currentPassword === 'employee')) isMatch = true;
          if (activeSession.role === 'admin' && uname !== 'admin') isMatch = true;
          if (!isMatch) {
            return makeResponse({ error: "Incorrect current password." }, 401);
          }
          users[idx].password = body.newPassword;
          saveDbData('users', users);
          return makeResponse({ success: true, message: "Password updated successfully." });
        }
      }

      if (path === '/api/clinic/details') {
        if (method === 'GET') {
          const saved = localStorage.getItem("madrasortho_clinic_branding");
          const parsed = saved ? JSON.parse(saved) : {};
          return makeResponse({
            name: parsed.name || "MADRAS ORTHO CLINIC & PHARMACY",
            description: parsed.description || "Center for Orthopaedic Surgery & Trauma Care",
            address: parsed.address || "42 Anna Salai, Thousand Lights, Chennai - 600002, Tamil Nadu",
            city: parsed.city || "Chennai",
            state: parsed.state || "Tamil Nadu",
            pincode: parsed.pincode || "600002",
            phone: parsed.phone || "+91 44 2855 0123 / +91 98401 22334",
            email: parsed.email || "contact@madrasortho.com",
            gstin: parsed.gstin || "33AAAAA0000A1Z5",
            dlNo: parsed.dlNo || "20B/TN/CHE/00482",
            dlNo21: parsed.dlNo21 || "21B/TN/CHE/00482",
            ceaNo: parsed.ceaNo || "TN/CEA/2018/CHE-0482",
            doctorName: parsed.doctorName || "Dr. Arjun Sharma, MS (Ortho)",
            doctorDegrees: parsed.doctorDegrees || "MBBS, MS (Orthopaedics), MCh (Orth)",
            doctorRegNo: parsed.doctorRegNo || "TNMC/2012/94821",
            doctorCouncil: parsed.doctorCouncil || "Tamil Nadu Medical Council",
            doctorSpecialty: parsed.doctorSpecialty || "Chief Orthopaedic Surgeon & Joint Replacement Specialist",
            doctorPhone: parsed.doctorPhone || "+91 98402 33445",
            doctorEmail: parsed.doctorEmail || "arjun@madrasortho.com",
            pharmacistName: parsed.pharmacistName || "Priya Nair, B.Pharm",
            pharmacistRegNo: parsed.pharmacistRegNo || "TNSPC/2018/48912",
            stateCouncil: parsed.stateCouncil || "Tamil Nadu State Pharmacy Council",
            adminUsername: "admin"
          });
        }
        if (method === 'PUT' || method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const current = localStorage.getItem("madrasortho_clinic_branding");
          const updated = { ...(current ? JSON.parse(current) : {}), ...body };
          localStorage.setItem("madrasortho_clinic_branding", JSON.stringify(updated));
          return makeResponse({ success: true, message: "Clinic & Doctor Admin details saved successfully.", details: updated });
        }
      }

      // ----------------------------------------------------
      // PRODUCTS API
      // ----------------------------------------------------
      if (path === '/api/products') {
        let products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);

        if (method === 'GET') {
          const batches = getDbData('batches', []);
          const todayIso = new Date().toISOString().split('T')[0];

          const enriched = products.map((p: any) => {
            const pBatches = batches.filter((b: any) => b.product_id === p.id);
            const activeNonExpired = pBatches.filter((b: any) => {
              const bExp = String(b.expiry_date || '').substring(0, 10);
              return bExp > todayIso && b.status !== 'Quarantined' && b.status !== 'Recalled';
            });
            const totalStock = activeNonExpired.length > 0
              ? activeNonExpired.reduce((sum: number, b: any) => sum + Math.max(0, Number(b.available_stock || 0)), 0)
              : (p.available_stock !== undefined ? p.available_stock : (p.status === 'Out of Stock' ? 0 : 50));

            const sorted = [...activeNonExpired].sort((a: any, b: any) => String(a.expiry_date).localeCompare(String(b.expiry_date)));
            const primaryBatch = sorted[0] || pBatches[0];

            const isExpired = pBatches.length > 0 && activeNonExpired.length === 0;
            const isOutOfStock = totalStock <= 0;
            const intelligentStatus = isExpired ? 'Expired' : (isOutOfStock ? 'Out of Stock' : 'Available');

            return {
              ...p,
              mrp: Number(p.mrp || primaryBatch?.mrp || p.price),
              price: Number(p.price),
              purchase_price: Number(p.purchase_price || primaryBatch?.purchase_price || +(p.price * 0.75).toFixed(2)),
              available_stock: totalStock,
              batch_number: primaryBatch?.batch_number || p.batch_number || `B-2026-${String(p.id).padStart(4, '0')}`,
              expiry_date: primaryBatch?.expiry_date || p.expiry_date || '2028-12-31',
              is_expired: isExpired,
              is_out_of_stock: isOutOfStock,
              status: intelligentStatus
            };
          });

          enriched.sort((a: any, b: any) => (a.name || '').localeCompare(b.name || ''));
          return makeResponse(enriched);
        }

        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          if (!body.name || !body.category || body.price === undefined) {
            return makeResponse({ error: "Missing required product fields." }, 400);
          }
          const newId = products.length > 0 ? Math.max(...products.map((p: any) => Number(p.id) || 0)) + 1 : 1;
          const sellingPrice = Number(body.price);
          const mrp = Number(body.mrp !== undefined ? body.mrp : sellingPrice);
          const purchasePrice = Number(body.purchase_price || 0);
          const initialStock = Number(body.initial_stock || body.available_stock || 0);
          const batchNo = String(body.batch_number || `B-2026-${String(newId).padStart(4, '0')}`);
          const expDate = String(body.expiry_date || '2028-12-31');

          const newProduct = {
            id: newId,
            name: body.name,
            category: body.category,
            price: sellingPrice,
            mrp: mrp,
            purchase_price: purchasePrice,
            available_stock: initialStock,
            batch_number: batchNo,
            expiry_date: expDate,
            barcode: body.barcode || null,
            sku: body.sku || null,
            tax_percent: Number(body.tax_percent || 0),
            status: initialStock > 0 ? 'Available' : 'Out of Stock',
            quantity_type: body.quantity_type || 'strip',
            is_example: 0
          };
          products.push(newProduct);
          saveDbData('products', products);

          if (initialStock > 0) {
            let batches = getDbData('batches', []);
            batches.push({
              id: batches.length + 1,
              product_id: newId,
              batch_number: batchNo,
              mfg_date: '2026-01-01',
              expiry_date: expDate,
              mrp: mrp,
              selling_price: sellingPrice,
              purchase_price: purchasePrice,
              available_stock: initialStock,
              status: 'Active'
            });
            saveDbData('batches', batches);

            let inwardList = getDbData('inward_stock', []);
            inwardList.unshift({
              id: inwardList.length + 1,
              product_id: newId,
              product_name: body.name,
              batch_number: batchNo,
              quantity: initialStock,
              expiry_date: expDate,
              purchase_price: purchasePrice,
              mrp: mrp,
              selling_price: sellingPrice,
              received_date: new Date().toISOString().split('T')[0],
              received_by: 'Admin'
            });
            saveDbData('inward_stock', inwardList);
          }

          return makeResponse(newProduct, 201);
        }
      }

      if (path === '/api/products/parse-excel' && method === 'POST') {
        const body = JSON.parse(init?.body as string || '{}');
        const text = body.csvText || '';
        // Fast mock CSV parsing
        const lines = text.split(/\r?\n/).filter((l: string) => l.trim().length > 0);
        const medicines: any[] = [];
        let headerPassed = false;
        lines.forEach((line: string) => {
          if (!headerPassed) {
            if (line.toLowerCase().includes('name') || line.toLowerCase().includes('medicine') || line.toLowerCase().includes('product')) {
              headerPassed = true;
            }
            return;
          }
          const parts = line.split(',').map((p: string) => p.replace(/^"|"$/g, '').trim());
          if (parts[0] && !parts[0].toLowerCase().includes('instructions:')) {
            medicines.push({
              name: parts[0],
              category: parts[1] || 'Orthopaedic Medicines',
              price: parseFloat((parts[2] || '0').replace(/[^0-9.]/g, '')) || 0,
              tax_percent: parseFloat((parts[3] || '5').replace(/[^0-9.]/g, '')) || 5,
              quantity_type: parts[4] || 'strip',
              barcode: parts[5] || null,
              sku: parts[6] || null,
              status: 'Available'
            });
          }
        });
        return makeResponse({ success: true, count: medicines.length, filename: body.filename || 'uploaded.csv', medicines });
      }

      if (path === '/api/products/batch') {
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const batchList = body.products || [];
          const updateExisting = !!body.updateExisting;
          let products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);
          let added = 0;
          let updated = 0;
          let currentMaxId = products.length > 0 ? Math.max(...products.map((p: any) => Number(p.id) || 0)) : 0;

          for (const item of batchList) {
            if (!item.name) continue;
            const existingIdx = products.findIndex((p: any) => (p.name || '').trim().toLowerCase() === (item.name || '').trim().toLowerCase());
            if (existingIdx !== -1) {
              if (updateExisting) {
                products[existingIdx] = {
                  ...products[existingIdx],
                  category: item.category || products[existingIdx].category,
                  price: Number(item.price) || products[existingIdx].price,
                  tax_percent: item.tax_percent !== undefined ? Number(item.tax_percent) : products[existingIdx].tax_percent,
                  quantity_type: item.quantity_type || products[existingIdx].quantity_type,
                  barcode: item.barcode || products[existingIdx].barcode,
                  sku: item.sku || products[existingIdx].sku
                };
                updated++;
              } else {
                currentMaxId++;
                products.push({
                  id: currentMaxId,
                  name: `${item.name} (${currentMaxId})`,
                  category: item.category || 'Orthopaedic Medicines',
                  price: Number(item.price) || 0,
                  tax_percent: Number(item.tax_percent) || 5,
                  barcode: item.barcode || null,
                  sku: item.sku || null,
                  status: item.status || 'Available',
                  quantity_type: item.quantity_type || 'strip'
                });
                added++;
              }
            } else {
              currentMaxId++;
              products.push({
                id: currentMaxId,
                name: item.name.trim(),
                category: item.category || 'Orthopaedic Medicines',
                price: Number(item.price) || 0,
                tax_percent: Number(item.tax_percent) || 5,
                barcode: item.barcode || null,
                sku: item.sku || null,
                status: item.status || 'Available',
                quantity_type: item.quantity_type || 'strip'
              });
              added++;
            }
          }
          saveDbData('products', products);
          return makeResponse({ success: true, added, updated, totalProcessed: batchList.length });
        }
      }

      if (path.startsWith('/api/products/')) {
        const idStr = path.substring('/api/products/'.length);

        if (idStr.startsWith('barcode/')) {
          const barcode = idStr.substring('barcode/'.length);
          const products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);
          const product = products.find((p: any) => p.barcode === barcode && p.status === 'Available');
          if (!product) {
            return makeResponse({ error: "Product not found." }, 404);
          }
          return makeResponse(product);
        }

        const id = Number(idStr);
        let products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);
        const idx = products.findIndex((p: any) => p.id === id);

        if (idx === -1) {
          return makeResponse({ error: "Product not found." }, 404);
        }

        if (method === 'PUT') {
          const body = JSON.parse(init?.body as string || '{}');
          const updated = {
            ...products[idx],
            name: body.name !== undefined ? body.name : products[idx].name,
            category: body.category !== undefined ? body.category : products[idx].category,
            price: body.price !== undefined ? Number(body.price) : products[idx].price,
            mrp: body.mrp !== undefined ? Number(body.mrp) : (products[idx].mrp || products[idx].price),
            purchase_price: body.purchase_price !== undefined ? Number(body.purchase_price) : products[idx].purchase_price,
            barcode: body.barcode !== undefined ? body.barcode : products[idx].barcode,
            sku: body.sku !== undefined ? body.sku : products[idx].sku,
            tax_percent: body.tax_percent !== undefined ? Number(body.tax_percent) : products[idx].tax_percent,
            status: body.status !== undefined ? body.status : products[idx].status,
            quantity_type: body.quantity_type !== undefined ? body.quantity_type : products[idx].quantity_type
          };
          products[idx] = updated;
          saveDbData('products', products);
          return makeResponse(updated);
        }

        if (method === 'DELETE') {
          const prod = products[idx];
          const isExample = prod.is_example === 1 || prod.is_example === true || prod.is_example === undefined;
          if (!isExample) {
            return makeResponse({
              error: "Statutory Pharmacy Inventory Protection: Actual clinic inventory items cannot be deleted to preserve drug dispensing audit trail. Set stock to 0 or mark 'Inactive' instead. Only pre-seeded example items can be deleted."
            }, 403);
          }
          products.splice(idx, 1);
          saveDbData('products', products);
          return makeResponse({ message: `Example medicine ${prod.name} deleted successfully.`, id });
        }
      }

      // ----------------------------------------------------
      // EMPLOYEES API
      // ----------------------------------------------------
      if (path === '/api/employees') {
        let employees = getDbData('employees', DEFAULT_EMPLOYEES);

        if (method === 'GET') {
          employees.sort((a: any, b: any) => (a.name || '').localeCompare(b.name || ''));
          const sanitized = activeSession.role === 'admin' ? employees : employees.map(({ salary, ...rest }: any) => rest);
          return makeResponse(sanitized);
        }

        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const newId = employees.length > 0 ? Math.max(...employees.map((e: any) => Number(e.id) || 0)) + 1 : 1;
          const newEmp = {
            id: newId,
            name: body.name,
            role: body.role,
            phone: body.phone || null,
            email: body.email || null,
            salary: body.salary !== undefined && body.salary !== null ? Number(body.salary) : null,
            status: body.status || 'Active',
            joined_date: body.joined_date || new Date().toISOString().split('T')[0],
            qualification: body.qualification || null,
            reg_no: body.reg_no || null,
            is_example: 0
          };
          employees.push(newEmp);
          saveDbData('employees', employees);
          return makeResponse(newEmp, 201);
        }
      }

      if (path.startsWith('/api/employees/')) {
        const id = Number(path.substring('/api/employees/'.length));
        let employees = getDbData('employees', DEFAULT_EMPLOYEES);
        const idx = employees.findIndex((e: any) => e.id === id);

        if (idx === -1) {
          return makeResponse({ error: "Employee not found." }, 404);
        }

        if (method === 'PUT') {
          const body = JSON.parse(init?.body as string || '{}');
          const updated = {
            ...employees[idx],
            name: body.name !== undefined ? body.name : employees[idx].name,
            role: body.role !== undefined ? body.role : employees[idx].role,
            phone: body.phone !== undefined ? body.phone : employees[idx].phone,
            email: body.email !== undefined ? body.email : employees[idx].email,
            salary: body.salary !== undefined && body.salary !== null ? Number(body.salary) : employees[idx].salary,
            status: body.status !== undefined ? body.status : employees[idx].status,
            joined_date: body.joined_date !== undefined ? body.joined_date : employees[idx].joined_date,
            qualification: body.qualification !== undefined ? body.qualification : employees[idx].qualification,
            reg_no: body.reg_no !== undefined ? body.reg_no : employees[idx].reg_no
          };
          employees[idx] = updated;
          saveDbData('employees', employees);
          return makeResponse(updated);
        }

        if (method === 'DELETE') {
          const emp = employees[idx];
          const isExample = emp.is_example === 1 || emp.is_example === true;
          if (!isExample) {
            return makeResponse({
              error: "Statutory Protection: Genuine clinic staff and registered pharmacist employment records cannot be deleted. You can mark their employment status as 'Inactive' instead. Only pre-seeded example employee records may be removed."
            }, 403);
          }
          employees.splice(idx, 1);
          saveDbData('employees', employees);
          return makeResponse({ message: `Example staff record ${emp.name} deleted successfully.`, id });
        }
      }

      // ----------------------------------------------------
      // BILLS & INVOICES API
      // ----------------------------------------------------
      if (path === '/api/bills/next-number') {
        const bills = getDbData('bills', []);
        const todayStr = new Date().toISOString().split('T')[0];
        const todaysBills = bills.filter((b: any) => (b.date || '').startsWith(todayStr));
        const nextVal = todaysBills.length > 0 ? Math.max(...todaysBills.map((b: any) => Number(b.bill_number) || 0)) + 1 : 1;
        return makeResponse({ nextBillNumber: nextVal });
      }


      // ----------------------------------------------------
      // PATIENT PROFILES API (OFFLINE MOCK DB)
      // ----------------------------------------------------
      if (path === '/api/patients') {
        let patients = getDbData('patients', DEFAULT_PATIENTS);
        if (method === 'GET') {
          const q = (params.get('search') || '').trim().toLowerCase();
          if (!q) {
            patients.sort((a: any, b: any) => (a.name || '').localeCompare(b.name || ''));
            return makeResponse(patients);
          }
          const filtered = patients.filter((p: any) => {
            const matchMrn = (p.patient_id || '').toLowerCase().includes(q);
            const matchName = (p.name || '').toLowerCase().includes(q);
            const matchPhone = (p.phone || '').replace(/\D/g, '').includes(q.replace(/\D/g, ''));
            const matchGuardian = (p.guardian_name || '').toLowerCase().includes(q);
            const matchArea = (p.address || '').toLowerCase().includes(q);
            return matchMrn || matchName || matchPhone || matchGuardian || matchArea;
          });
          return makeResponse(filtered);
        }

        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          if (!body.name || !body.name.trim()) {
            return makeResponse({ error: "Patient name is mandatory." }, 400);
          }
          const year = new Date().getFullYear();
          let mrn = (body.patient_id || '').trim();
          if (!mrn) {
            let maxNum = 0;
            patients.forEach((p: any) => {
              if (p.patient_id && p.patient_id.startsWith(`MOC-${year}-`)) {
                const numPart = parseInt(p.patient_id.split('-')[2], 10);
                if (!isNaN(numPart) && numPart > maxNum) maxNum = numPart;
              }
            });
            mrn = `MOC-${year}-${String(maxNum + 1).padStart(4, '0')}`;
          }

          if (patients.some((p: any) => (p.patient_id || '').toLowerCase() === mrn.toLowerCase())) {
            return makeResponse({ error: `Patient ID '${mrn}' already exists.` }, 400);
          }

          const nextId = patients.length > 0 ? Math.max(...patients.map((p: any) => Number(p.id) || 0)) + 1 : 1;
          const newPatient = {
            id: nextId,
            patient_id: mrn,
            name: body.name.trim(),
            age: body.age ? Number(body.age) : null,
            gender: body.gender || 'Other',
            guardian_name: body.guardian_name || '',
            phone: body.phone || '',
            email: body.email || '',
            address: body.address || 'Chennai',
            city: body.city || 'Chennai',
            pincode: body.pincode || '',
            blood_group: body.blood_group || '',
            known_allergies: body.known_allergies || '',
            chronic_conditions: body.chronic_conditions || '',
            attending_doctor: body.attending_doctor || 'Dr. Arjun Sharma, MS (Ortho)',
            notes: body.notes || '',
            created_at: new Date().toISOString()
          };
          patients.push(newPatient);
          saveDbData('patients', patients);
          return makeResponse(newPatient, 201);
        }
      }

      if (path === '/api/patients/next-mrn') {
        const patients = getDbData('patients', DEFAULT_PATIENTS);
        const year = new Date().getFullYear();
        let maxNum = 0;
        patients.forEach((p: any) => {
          if (p.patient_id && p.patient_id.startsWith(`MOC-${year}-`)) {
            const numPart = parseInt(p.patient_id.split('-')[2], 10);
            if (!isNaN(numPart) && numPart > maxNum) maxNum = numPart;
          }
        });
        return makeResponse({ nextMrn: `MOC-${year}-${String(maxNum + 1).padStart(4, '0')}` });
      }

      if (path.startsWith('/api/patients/') && path.endsWith('/history')) {
        const idOrMrn = path.replace('/api/patients/', '').replace('/history', '');
        const patients = getDbData('patients', DEFAULT_PATIENTS);
        const patient = patients.find((p: any) => String(p.id) === idOrMrn || (p.patient_id || '').toLowerCase() === idOrMrn.toLowerCase());
        if (!patient) return makeResponse({ error: "Patient not found." }, 404);

        const bills = getDbData('bills', []);
        const matched = bills.filter((b: any) => {
          const matchMrn = b.clinic_patient_id && (b.clinic_patient_id.toLowerCase() === (patient.patient_id || '').toLowerCase());
          const matchPhone = b.patient_phone && patient.phone && b.patient_phone.replace(/\D/g, '') === patient.phone.replace(/\D/g, '');
          const matchName = b.patient_name && patient.name && b.patient_name.trim().toLowerCase() === patient.name.trim().toLowerCase();
          return matchMrn || matchPhone || matchName;
        });

        return makeResponse({
          patient,
          totalVisits: matched.length,
          history: matched
        });
      }

      if (path.startsWith('/api/patients/')) {
        const idOrMrn = path.replace('/api/patients/', '');
        let patients = getDbData('patients', DEFAULT_PATIENTS);
        const idx = patients.findIndex((p: any) => String(p.id) === idOrMrn || (p.patient_id || '').toLowerCase() === idOrMrn.toLowerCase());

        if (method === 'GET') {
          if (idx === -1) return makeResponse({ error: "Patient not found." }, 404);
          return makeResponse(patients[idx]);
        }

        if (method === 'PUT') {
          if (idx === -1) return makeResponse({ error: "Patient not found." }, 404);
          const body = JSON.parse(init?.body as string || '{}');
          patients[idx] = { ...patients[idx], ...body, updated_at: new Date().toISOString() };
          saveDbData('patients', patients);
          return makeResponse(patients[idx]);
        }

        if (method === 'DELETE') {
          if (idx === -1) return makeResponse({ error: "Patient not found." }, 404);
          const p = patients[idx];
          const isExample = p.is_example === 1 || p.is_example === true;
          if (!isExample) {
            return makeResponse({
              error: "Medical Records Protection: Actual registered patient clinical records are legally protected under the Tamil Nadu Clinical Establishments Act and Medical Council Regulations. Only pre-seeded example/demo patient records may be deleted."
            }, 403);
          }
          patients.splice(idx, 1);
          saveDbData('patients', patients);
          return makeResponse({ success: true, message: `Example patient record ${p.name} (${p.patient_id}) deleted successfully.`, id: p.id });
        }
      }


      if (path === '/api/bills') {
        let bills = getDbData('bills', []);

        if (method === 'GET') {
          const mode = params.get('mode');
          if (mode && mode !== 'ALL') {
            bills = bills.filter((b: any) => b.operating_mode === mode);
          }
          const period = params.get('period') || 'day';
          const dateStr = params.get('date') || new Date().toISOString().split('T')[0];
          const year = Number(params.get('year') || new Date().getFullYear());

          let filteredBills = [];

          if (period === 'day') {
            filteredBills = bills.filter((b: any) => (b.date || '').startsWith(dateStr));
          } else if (period === 'week') {
            const { monday, sunday } = getMondayAndSunday(dateStr);
            filteredBills = bills.filter((b: any) => b.date >= monday && b.date <= sunday);
          } else if (period === 'month') {
            const monthParam = params.get('month') || (dateStr && dateStr.substring(0, 7)) || new Date().toISOString().substring(0, 7);
            filteredBills = bills.filter((b: any) => (b.date || '').startsWith(monthParam));
          } else if (period === 'year') {
            filteredBills = bills.filter((b: any) => (b.date || '').startsWith(`${year}-`));
          } else {
            filteredBills = bills;
          }

          filteredBills.sort((a: any, b: any) => {
            const dateDiff = (b.date || '').localeCompare(a.date || '');
            if (dateDiff !== 0) return dateDiff;
            return (b.time || '').localeCompare(a.time || '');
          });

          return makeResponse(filteredBills);
        }

        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const isComplimentary = Boolean(body.is_complimentary || body.payment_method === 'Complimentary');
          if (isComplimentary && activeSession.role !== 'admin') {
            return makeResponse({ error: "Access Denied: Only Admin accounts can issue complimentary bills." }, 403);
          }
          const now = new Date();
          const dateStr = now.toISOString().split('T')[0];
          const timeStr = now.toTimeString().split(' ')[0];
          const items = body.items || [];

          // Intelligent Stock & Expiry Guardrails System
          let batches = getDbData('batches', []);
          for (const it of items) {
            const prodName = it.product_name || it.name || 'Medicine';
            const expDate = String(it.expiry_date || '').substring(0, 10);
            if (expDate && expDate <= dateStr) {
              return makeResponse({
                error: `CRITICAL STATUTORY VIOLATION: Cannot dispense EXPIRED medicine '${prodName}' (Expiry: ${it.expiry_date}). Sale blocked under Rule 65.`
              }, 400);
            }

            const pBatches = batches.filter((b: any) => b.product_id === it.product_id || b.batch_number === it.batch_number);
            const activeBatches = pBatches.filter((b: any) => String(b.expiry_date).substring(0, 10) > dateStr);
            const totalStock = activeBatches.reduce((sum: number, b: any) => sum + Math.max(0, Number(b.available_stock || 0)), 0);

            if (pBatches.length > 0) {
              if (totalStock <= 0) {
                return makeResponse({
                  error: `DISPENSING BLOCKED: '${prodName}' is OUT OF STOCK. Cannot be billed.`
                }, 400);
              }
              if (Number(it.quantity || 1) > totalStock) {
                return makeResponse({
                  error: `DISPENSING BLOCKED: Insufficient stock for '${prodName}'. Requested: ${it.quantity}, Available: ${totalStock}.`
                }, 400);
              }
            }
          }

          const round2 = (v: unknown) => {
            const n = Number(v ?? 0);
            return Number.isFinite(n) ? Math.round((n + Number.EPSILON) * 100) / 100 : 0;
          };
          const newId = bills.length > 0 ? Math.max(...bills.map((b: any) => Number(b.id) || 0)) + 1 : 1;
          const newBill = {
            id: newId,
            bill_number: typeof body.bill_number === 'number' ? body.bill_number : (parseInt(String(body.bill_number).replace(/\D/g, ''), 10) || body.bill_number || 1),
            subtotal: isComplimentary ? 0 : round2(body.subtotal || 0),
            discount: isComplimentary ? 0 : round2(body.discount || 0),
            tax: isComplimentary ? 0 : round2(body.tax || 0),
            grand_total: isComplimentary ? 0 : round2(body.grand_total || 0),
            payment_method: isComplimentary ? 'Complimentary' : (body.payment_method || 'Cash'),
            is_complimentary: isComplimentary ? 1 : 0,
            complimentary_recipient: body.complimentary_recipient || null,
            complimentary_reason: body.complimentary_reason || null,
            date: dateStr,
            time: timeStr,
            cashier_name: body.cashier_name || 'Pharmacist',
            patient_name: (body.patient_name || '').trim() || (isComplimentary ? (body.complimentary_recipient || 'Doctor / Staff Beneficiary') : 'Walk-in Patient'),
            patient_phone: body.patient_phone || null,
            operating_mode: body.operating_mode || 'CLINIC_DISPENSING',
            status: 'Active',
            items: items.map((it: any) => ({
              product_id: it.product_id,
              product_name: it.product_name,
              quantity: Number(it.quantity || 1),
              rate: round2(it.rate || 0),
              mrp: round2(it.mrp || it.rate || 0),
              purchase_price: round2(it.purchase_price || 0),
              total: isComplimentary ? 0 : round2(it.total ?? (Number(it.rate || 0) * Number(it.quantity || 1))),
              batch_number: it.batch_number || 'B-STD',
              expiry_date: it.expiry_date || '2028-12-31'
            }))
          };
          bills.push(newBill);
          saveDbData('bills', bills);

          // Decrement stock in local batches with FEFO multi-batch allocation
          try {
            items.forEach((it: any) => {
              let req = Number(it.quantity || 1);
              const prodBatches = batches
                .filter((bat: any) => bat.product_id === it.product_id && Number(bat.available_stock || 0) > 0)
                .sort((a: any, b: any) => String(a.expiry_date || '').localeCompare(String(b.expiry_date || '')));
              if (prodBatches.length > 0) {
                for (const b of prodBatches) {
                  if (req <= 0) break;
                  const ded = Math.min(req, Number(b.available_stock || 0));
                  b.available_stock = Math.max(0, Number(b.available_stock || 0) - ded);
                  req -= ded;
                }
              } else {
                const match = batches.find((bat: any) => bat.batch_number === it.batch_number || bat.product_id === it.product_id);
                if (match) {
                  match.available_stock = Math.max(0, Number(match.available_stock || 0) - req);
                }
              }
            });
            saveDbData('batches', batches);
          } catch (e) {}

          return makeResponse(newBill, 201);
        }
      }

      if (path.startsWith('/api/bills/')) {
        const subPath = path.substring('/api/bills/'.length);

        if (subPath.endsWith('/items')) {
          const id = Number(subPath.substring(0, subPath.indexOf('/items')));
          const bills = getDbData('bills', []);
          const bill = bills.find((b: any) => b.id === id);
          return makeResponse(bill ? bill.items || [] : []);
        }

        if (subPath.endsWith('/cancel') && method === 'POST') {
          const id = Number(subPath.replace('/cancel', ''));
          let bills = getDbData('bills', []);
          const idx = bills.findIndex((b: any) => b.id === id);
          if (idx !== -1) {
            const body = JSON.parse(init?.body as string || '{}');
            bills[idx].status = 'Cancelled';
            bills[idx].cancel_reason = body.reason || 'Cancelled via statutory credit note';
            bills[idx].cancelled_at = new Date().toISOString();
            saveDbData('bills', bills);
            
            // Add audit log
            let audit = getDbData('audit_logs', []);
            audit.push({
              id: audit.length + 1,
              action: 'CANCEL_INVOICE_CREDIT_NOTE',
              entity: 'bills',
              entity_id: id,
              user_id: 1,
              username: 'pharmacist',
              details: JSON.stringify({ bill_number: bills[idx].bill_number, reason: bills[idx].cancel_reason }),
              created_at: new Date().toISOString()
            });
            saveDbData('audit_logs', audit);

            return makeResponse({ success: true, message: "Bill cancelled under statutory credit note.", bill: bills[idx] });
          }
          return makeResponse({ error: "Bill not found." }, 404);
        }

        const id = Number(subPath);
        let bills = getDbData('bills', []);
        const idx = bills.findIndex((b: any) => b.id === id);
        if (idx !== -1) {
          if (method === 'DELETE') {
            const b = bills[idx];
            const isExample = b.is_example === 1 || b.is_example === true;
            if (!isExample) {
              return makeResponse({
                error: "Statutory Violation: Invoices cannot be deleted under Rule 65 of D&C Rules and Section 36 of CGST Act. Only example bills can be deleted. Use Credit Note cancellation (/api/bills/:id/cancel)."
              }, 405);
            }
            bills.splice(idx, 1);
            saveDbData('bills', bills);
            return makeResponse({ success: true, message: `Example bill #${b.bill_number} deleted successfully.`, id: b.id });
          }
          return makeResponse(bills[idx]);
        }
        return makeResponse({ error: "Bill not found." }, 404);
      }

      // ----------------------------------------------------
      // DELETED ITEMS HISTORY AUDIT
      // ----------------------------------------------------
      if (path === '/api/deleted-items') {
        let logs = getDbData('deleted_items', []);

        if (method === 'GET') {
          logs.sort((a: any, b: any) => (b.deleted_at || '').localeCompare(a.deleted_at || ''));
          return makeResponse(logs.slice(0, 100));
        }

        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const newLog = {
            id: logs.length > 0 ? Math.max(...logs.map((l: any) => Number(l.id) || 0)) + 1 : 1,
            bill_id: body.bill_id ? Number(body.bill_id) : null,
            product_name: body.product_name || 'Item',
            quantity: Number(body.quantity || 1),
            deleted_at: new Date().toISOString()
          };
          logs.push(newLog);
          saveDbData('deleted_items', logs);
          return makeResponse({ success: true }, 201);
        }
      }

      // ----------------------------------------------------
      // NETWORK PRINTER MOCK
      // ----------------------------------------------------
      if (path === '/api/print/network') {
        return makeResponse({ success: true, message: "Receipt dispatched to printer." });
      }

      // ----------------------------------------------------
      // INWARD STOCK & CUSTOM CATEGORIES (MOCK / OFFLINE)
      // ----------------------------------------------------
      if (path === '/api/inventory/inward') {
        const inwardList = getDbData('inward_stock', []);
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          let batches = getDbData('batches', []);
          let products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);

          const itemsToProcess = Array.isArray(body.items) && body.items.length > 0
            ? body.items.map((it: any) => ({
                product_id: Number(it.product_id || 0),
                product_name: String(it.product_name || it.name || 'Medicine'),
                batch_number: String(it.batch_number || 'BTH-' + Date.now()),
                quantity: Number(it.quantity || it.quantity_received || 0),
                expiry_date: String(it.expiry_date || '2028-12-31'),
                mfg_date: it.mfg_date || '2026-01-01',
                purchase_price: Number(it.purchase_price || 0),
                mrp: Number(it.mrp || 0),
                selling_price: Number(it.selling_price !== undefined ? it.selling_price : (it.mrp || 0)),
                supplier_name: body.supplier_name || 'Direct Wholesale',
                invoice_number: body.invoice_number || 'INV-MONTHLY',
                received_date: body.received_date || new Date().toISOString().split('T')[0],
                received_by: body.received_by || 'Admin',
                notes: body.notes || ''
              }))
            : [{
                product_id: Number(body.product_id || 0),
                product_name: String(body.product_name || 'Medicine'),
                batch_number: String(body.batch_number),
                quantity: Number(body.quantity || body.quantity_received || 0),
                expiry_date: String(body.expiry_date),
                mfg_date: body.mfg_date || '2026-01-01',
                purchase_price: Number(body.purchase_price || 0),
                mrp: Number(body.mrp || 0),
                selling_price: Number(body.selling_price !== undefined ? body.selling_price : (body.mrp || 0)),
                supplier_name: body.supplier_name || 'Direct Wholesale',
                invoice_number: body.invoice_number || 'INV-MONTHLY',
                received_date: body.received_date || new Date().toISOString().split('T')[0],
                received_by: body.received_by || 'Admin',
                notes: body.notes || ''
              }];

          let totalCost = 0;
          let totalUnits = 0;

          for (const item of itemsToProcess) {
            let pid = item.product_id;
            if (pid <= 0 && item.product_name) {
              const found = products.find((p: any) => p.name.toLowerCase() === item.product_name.toLowerCase());
              if (found) {
                pid = found.id;
              } else {
                pid = products.length > 0 ? Math.max(...products.map((p: any) => Number(p.id) || 0)) + 1 : 1;
                products.push({
                  id: pid,
                  name: item.product_name,
                  category: 'General Medicine',
                  price: item.selling_price,
                  mrp: item.mrp,
                  purchase_price: item.purchase_price,
                  status: 'Available',
                  tax_percent: 12
                });
              }
              item.product_id = pid;
            }

            const newId = inwardList.length > 0 ? Math.max(...inwardList.map((r: any) => Number(r.id) || 0)) + 1 : 1;
            const newEntry = {
              id: newId,
              ...item,
              created_at: new Date().toISOString()
            };
            inwardList.unshift(newEntry);

            // Sync into batches
            const existing = batches.find((b: any) => b.product_id === pid && b.batch_number === item.batch_number);
            if (existing) {
              existing.available_stock = Number(existing.available_stock || 0) + item.quantity;
              existing.expiry_date = item.expiry_date;
              existing.purchase_price = item.purchase_price;
              existing.mrp = item.mrp;
              existing.selling_price = item.selling_price;
              existing.status = 'Active';
            } else {
              const nextBId = batches.length > 0 ? Math.max(...batches.map((b: any) => Number(b.id) || 0)) + 1 : 1;
              batches.push({
                id: nextBId,
                product_id: pid,
                batch_number: item.batch_number,
                mfg_date: item.mfg_date,
                expiry_date: item.expiry_date,
                mrp: item.mrp,
                selling_price: item.selling_price,
                purchase_price: item.purchase_price,
                available_stock: item.quantity,
                rack_location: 'MAIN-DISPENSARY',
                status: 'Active',
                created_at: new Date().toISOString()
              });
            }

            // Sync product active catalogue selling rate, MRP, and purchase cost
            const pIdx = products.findIndex((p: any) => p.id === pid);
            if (pIdx !== -1) {
              products[pIdx].price = item.selling_price;
              products[pIdx].mrp = item.mrp;
              products[pIdx].purchase_price = item.purchase_price;
              products[pIdx].status = 'Available';
            }

            totalCost += (item.quantity * item.purchase_price);
            totalUnits += item.quantity;
          }

          saveDbData('inward_stock', inwardList);
          saveDbData('batches', batches);
          saveDbData('products', products);

          return Promise.resolve({
            ok: true,
            status: 201,
            json: async () => ({
              success: true,
              count: itemsToProcess.length,
              total_units: totalUnits,
              total_purchase_cost: totalCost,
              message: `Recorded inward stock of ${itemsToProcess.length} medicines totaling ₹${totalCost.toFixed(2)}`
            })
          } as Response);
        }
        return makeResponse(inwardList);
      }

      if (path === '/api/categories') {
        const catList = getDbData('custom_categories', []);
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const name = String(body.name || '').trim();
          if (!name) return makeResponse({ error: "Category name is required" }, 400);
          const existing = catList.find((c: any) => c.name.toLowerCase() === name.toLowerCase());
          if (existing) return makeResponse({ success: true, category: existing });
          const newId = catList.length > 0 ? Math.max(...catList.map((c: any) => Number(c.id) || 0)) + 1 : 1;
          const entry = { id: newId, name, description: body.description || '', created_by: body.created_by || 'admin', created_at: new Date().toISOString() };
          catList.push(entry);
          saveDbData('custom_categories', catList);
          return makeResponse({ success: true, id: newId, name }, 201);
        }
        // Return custom categories sorted so newly created categories appear first
        const sortedCats = [...catList].sort((a: any, b: any) => (Number(b.id) || 0) - (Number(a.id) || 0) || (b.created_at || '').localeCompare(a.created_at || ''));
        return makeResponse(sortedCats);
      }

      if (path.startsWith('/api/categories/')) {
        const catName = decodeURIComponent(path.substring('/api/categories/'.length));
        if (method === 'DELETE') {
          let catList = getDbData('custom_categories', []);
          catList = catList.filter((c: any) => c.name.toLowerCase() !== catName.toLowerCase());
          saveDbData('custom_categories', catList);
          return makeResponse({ success: true, message: `Category '${catName}' deleted` });
        }
      }

      // ----------------------------------------------------
      // NOTIFICATIONS / REAL-TIME EXPIRY & STOCK ALERTS (MOCK)
      // ----------------------------------------------------
      if (path === '/api/notifications') {
        const today = new Date().toISOString().split('T')[0];
        const products = getDbData('products', ORTHO_PHARMACY_PRODUCTS);
        const batches = getDbData('batches', []);
        const prodMap = new Map<number, any>();
        products.forEach((p: any) => prodMap.set(p.id, p));

          const expired: any[] = [];
          const expiringSoon: any[] = [];
          const activeStockByProd = new Map<number, number>();
          batches.forEach((b: any) => {
            const p = prodMap.get(b.product_id);
            const prodName = p ? p.name : 'Unknown Medicine';
            const avail = Math.max(0, Number(b.available_stock || 0));
            const expDate = String(b.expiry_date || '').substring(0, 10);
            if (!expDate) return;
            const diffDays = Math.ceil((new Date(expDate).getTime() - new Date(today).getTime()) / (1000 * 60 * 60 * 24));
            if (diffDays > 0 && b.status !== 'Quarantined' && b.status !== 'Recalled' && avail > 0) {
              activeStockByProd.set(b.product_id, (activeStockByProd.get(b.product_id) || 0) + avail);
            }
            if (diffDays <= 0) {
              if (avail > 0 || b.status === 'Quarantined') {
                expired.push({
                  id: `exp-${b.id}`,
                  batch_id: b.id,
                  product_id: b.product_id,
                  product_name: prodName,
                  batch_number: b.batch_number,
                  expiry_date: expDate,
                  available_stock: avail,
                  rack_location: b.rack_location || 'Dispensing Shelf',
                  days_overdue: Math.abs(diffDays),
                  severity: 'CRITICAL',
                  type: 'EXPIRED',
                  title: `EXPIRED: ${prodName}`,
                  message: `Batch ${b.batch_number} expired on ${expDate} (${Math.abs(diffDays)} days ago). Remaining: ${avail} units. Must be isolated under Rule 65.`
                });
              }
            } else if (diffDays <= 60 && avail > 0) {
              expiringSoon.push({
                id: `soon-${b.id}`,
                batch_id: b.id,
                product_id: b.product_id,
                product_name: prodName,
                batch_number: b.batch_number,
                expiry_date: expDate,
                available_stock: avail,
                rack_location: b.rack_location || 'Dispensing Shelf',
                days_left: diffDays,
                severity: diffDays <= 30 ? 'HIGH' : 'MEDIUM',
                type: 'EXPIRING_SOON',
                title: `Expiring in ${diffDays} days: ${prodName}`,
                message: `Batch ${b.batch_number} expires on ${expDate}. Available: ${avail} units. Eligible for priority dispensing or wholesaler return.`
              });
            }
          });

          const outOfStock: any[] = [];
          const lowStock: any[] = [];
          products.forEach((p: any) => {
            const avail = activeStockByProd.has(p.id)
              ? (activeStockByProd.get(p.id) || 0)
              : Number(p.available_stock || 0);
            if (avail <= 0 || p.status === 'Out of Stock') {
              outOfStock.push({
                id: `oos-${p.id}`,
                product_id: p.id,
                product_name: p.name,
                category: p.category,
                mrp: p.mrp || p.price,
                severity: 'HIGH',
                type: 'OUT_OF_STOCK',
                title: `Out of Stock: ${p.name}`,
                message: `Zero available units remaining. Create inward stock intake to restore inventory.`
              });
            } else if (avail <= 15) {
              lowStock.push({
                id: `low-${p.id}`,
                product_id: p.id,
                product_name: p.name,
                category: p.category,
                available_stock: avail,
                severity: 'LOW',
                type: 'LOW_STOCK',
                title: `Low Stock (${avail} units left): ${p.name}`,
                message: `Only ${avail} units remaining in active clinic dispensary inventory.`
              });
            }
          });

          expired.sort((a, b) => b.days_overdue - a.days_overdue);
          expiringSoon.sort((a, b) => a.days_left - b.days_left);
          lowStock.sort((a, b) => (a.available_stock || 0) - (b.available_stock || 0));
          outOfStock.sort((a, b) => a.product_name.localeCompare(b.product_name));

          const getAlertRank = (item: any) =>
            (item.type === 'EXPIRING_SOON' || item.type === 'LOW_STOCK') ? 1 : (item.type === 'EXPIRED' ? 2 : 3);
          const allAlerts = [...expiringSoon, ...lowStock, ...expired, ...outOfStock].sort((a, b) => {
            const rankDiff = getAlertRank(a) - getAlertRank(b);
            if (rankDiff !== 0) return rankDiff;
            return String(a.product_name || '').localeCompare(String(b.product_name || ''));
          });
          const smartAlertsCount = expired.length + expiringSoon.length + lowStock.length;

          return makeResponse({
            summary: {
              totalAlerts: smartAlertsCount,
              smartAlertsCount,
              expiredCount: expired.length,
              expiringSoonCount: expiringSoon.length,
              outOfStockCount: outOfStock.length,
              lowStockCount: lowStock.length,
              updatedAt: new Date().toISOString()
            },
            allAlerts,
            expired,
            expiringSoon,
            outOfStock,
            lowStock
          });
      }

      // ----------------------------------------------------
      // REPORTS / SALES ANALYTICS
      // ----------------------------------------------------
      if (path.startsWith('/api/reports/')) {
        const reportType = path.substring('/api/reports/'.length);
        const bills = getDbData('bills', []);

        const computeMockStats = (billsList: any[], start: string, end: string, label: string) => {
          const activeBills = billsList.filter((b: any) => b.status !== 'Cancelled');
          const complimentaryBills = activeBills.filter((b: any) => Boolean(b.is_complimentary || b.payment_method === 'Complimentary'));
          const paidBills = activeBills.filter((b: any) => !b.is_complimentary && b.payment_method !== 'Complimentary');

          let netSales = 0;
          let grossSales = 0;
          let totalDiscounts = 0;
          let totalTax = 0;
          const paymentBreakdown = { Cash: 0, GooglePay: 0, BankCard: 0, Complimentary: 0 };
          const modeA = { revenue: 0, count: 0, tax: 0 };
          const modeB = { revenue: 0, count: 0, tax: 0 };

          const r2 = (v: unknown) => {
            const n = Number(v ?? 0);
            return Number.isFinite(n) ? Math.round((n + Number.EPSILON) * 100) / 100 : 0;
          };
          paidBills.forEach((b: any) => {
            const tot = r2(b.grand_total || 0);
            const disc = r2(b.discount || 0);
            const tx = r2(b.tax || 0);
            netSales = r2(netSales + tot);
            totalDiscounts = r2(totalDiscounts + disc);
            totalTax = r2(totalTax + tx);
            const pm = b.payment_method;
            if (pm === "Cash") paymentBreakdown.Cash = r2(paymentBreakdown.Cash + tot);
            else if (pm === "Google Pay" || pm === "GooglePay" || pm === "UPI") paymentBreakdown.GooglePay = r2(paymentBreakdown.GooglePay + tot);
            else if (pm === "Bank Card" || pm === "BankCard" || pm === "Card") paymentBreakdown.BankCard = r2(paymentBreakdown.BankCard + tot);

            if (b.operating_mode === 'RETAIL_PHARMACY') {
              modeB.revenue = r2(modeB.revenue + tot);
              modeB.count += 1;
              modeB.tax = r2(modeB.tax + tx);
            } else {
              modeA.revenue = r2(modeA.revenue + tot);
              modeA.count += 1;
              modeA.tax = r2(modeA.tax + tx);
            }
          });

          paymentBreakdown.Complimentary = complimentaryBills.length;

          let totalCogs = 0;
          let totalUnitsSold = 0;
          let totalComplimentaryUnits = 0;
          let complimentaryMrpValue = 0;
          const productsMap: { [key: string]: { name: string; quantity: number; total: number; cogs: number; profit: number } } = {};

          const gstSlabs = {
            slab0: { taxable: 0, cgst: 0, sgst: 0, totalTax: 0 },
            slab5: { taxable: 0, cgst: 0, sgst: 0, totalTax: 0 },
            slab12: { taxable: 0, cgst: 0, sgst: 0, totalTax: 0 },
            slab18: { taxable: 0, cgst: 0, sgst: 0, totalTax: 0 }
          };

          activeBills.forEach((b: any) => {
            if (b.items) {
              b.items.forEach((it: any) => {
                const qty = Number(it.quantity || 1);
                const rate = r2(it.rate || 0);
                const cost = r2(it.purchase_price ?? (rate * 0.72)); // Standard pharmacy acquisition rate
                const itemCogs = r2(qty * cost);

                if (b.is_complimentary || b.payment_method === 'Complimentary') {
                  totalComplimentaryUnits += qty;
                  complimentaryMrpValue = r2(complimentaryMrpValue + r2(qty * rate));
                } else {
                  totalUnitsSold += qty;
                  totalCogs = r2(totalCogs + itemCogs);
                  grossSales = r2(grossSales + r2(qty * rate));

                  const itTotal = r2(it.total || 0);
                  const taxRate = Math.round(Number(it.tax_percent || 0));
                  const taxable = r2(itTotal / (1 + (taxRate / 100)));
                  const totalLineTax = r2(itTotal - taxable);
                  const cgst = r2(totalLineTax / 2);
                  const sgst = r2(totalLineTax - cgst);
                  if (taxRate <= 2) gstSlabs.slab0.taxable = r2(gstSlabs.slab0.taxable + taxable);
                  else if (taxRate <= 6) { gstSlabs.slab5.taxable = r2(gstSlabs.slab5.taxable + taxable); gstSlabs.slab5.cgst = r2(gstSlabs.slab5.cgst + cgst); gstSlabs.slab5.sgst = r2(gstSlabs.slab5.sgst + sgst); gstSlabs.slab5.totalTax = r2(gstSlabs.slab5.totalTax + cgst + sgst); }
                  else if (taxRate <= 15) { gstSlabs.slab12.taxable = r2(gstSlabs.slab12.taxable + taxable); gstSlabs.slab12.cgst = r2(gstSlabs.slab12.cgst + cgst); gstSlabs.slab12.sgst = r2(gstSlabs.slab12.sgst + sgst); gstSlabs.slab12.totalTax = r2(gstSlabs.slab12.totalTax + cgst + sgst); }
                  else { gstSlabs.slab18.taxable = r2(gstSlabs.slab18.taxable + taxable); gstSlabs.slab18.cgst = r2(gstSlabs.slab18.cgst + cgst); gstSlabs.slab18.sgst = r2(gstSlabs.slab18.sgst + sgst); gstSlabs.slab18.totalTax = r2(gstSlabs.slab18.totalTax + cgst + sgst); }

                  if (!productsMap[it.product_name]) {
                    productsMap[it.product_name] = { name: it.product_name, quantity: 0, total: 0, cogs: 0, profit: 0 };
                  }
                  productsMap[it.product_name].quantity += qty;
                  productsMap[it.product_name].total = r2(productsMap[it.product_name].total + itTotal);
                  productsMap[it.product_name].cogs = r2(productsMap[it.product_name].cogs + itemCogs);
                  productsMap[it.product_name].profit = r2(productsMap[it.product_name].profit + (itTotal - itemCogs));
                }
              });
            }
          });

          if (grossSales === 0 && netSales > 0) grossSales = r2(netSales + totalDiscounts);
          const grossProfit = Math.max(0, r2(netSales - totalCogs));
          const profitMarginPercent = netSales > 0 ? r2((grossProfit / netSales) * 100) : 0;

          // Inward Stock
          const inwardList = getDbData('inward_stock', []).filter((r: any) => r.received_date >= start && r.received_date <= end);
          let totalInwardUnits = 0;
          let totalInwardCost = 0;
          let totalInwardMrp = 0;
          inwardList.forEach((inw: any) => {
            const q = Number(inw.quantity || 0);
            totalInwardUnits += q;
            totalInwardCost = r2(totalInwardCost + r2(q * Number(inw.purchase_price || 0)));
            totalInwardMrp = r2(totalInwardMrp + r2(q * Number(inw.mrp || 0)));
          });

          // Batches Closing Stock
          const batches = getDbData('batches', []);
          let closingStockUnits = 0;
          let closingStockCost = 0;
          let closingStockMrp = 0;
          batches.forEach((bat: any) => {
            const s = Math.max(0, Number(bat.available_stock || 0));
            closingStockUnits += s;
            closingStockCost = r2(closingStockCost + r2(s * Number(bat.purchase_price || (bat.mrp ? r2(bat.mrp * 0.72) : 50))));
            closingStockMrp = r2(closingStockMrp + r2(s * Number(bat.mrp || 70)));
          });

          const totalTaxRounded = r2(totalTax);
          const gstCgst = r2(totalTaxRounded / 2);
          const gstSgst = r2(totalTaxRounded - gstCgst);

          return {
            periodLabel: label,
            startDate: start,
            endDate: end,
            totalSales: netSales,
            grossSales: r2(grossSales),
            totalDiscounts: r2(totalDiscounts),
            discountedBillsCount: activeBills.filter((b: any) => Number(b.discount || 0) > 0).length,
            averageDiscountPercent: grossSales > 0 ? r2((totalDiscounts / grossSales) * 100) : 0,
            billCount: billsList.length,
            activeBillsCount: activeBills.length,
            cancelledBillsCount: billsList.filter((b: any) => b.status === 'Cancelled').length,
            financials: {
              grossSales: r2(grossSales),
              totalDiscounts: r2(totalDiscounts),
              netSales: r2(netSales),
              cogs: r2(totalCogs),
              grossProfit: r2(grossProfit),
              profitMarginPercent
            },
            stockMovement: {
              inwardUnits: totalInwardUnits,
              inwardPurchaseValuation: r2(totalInwardCost),
              inwardMrpValuation: r2(totalInwardMrp),
              unitsSold: totalUnitsSold,
              unitsSoldCost: r2(totalCogs),
              complimentaryUnits: totalComplimentaryUnits,
              complimentaryAbsorbedCost: 0,
              complimentaryCostAbsorbed: 0,
              netStockDifferenceUnits: totalInwardUnits - (totalUnitsSold + totalComplimentaryUnits),
              netStockValuationDifference: r2(totalInwardCost - totalCogs),
              currentAvailableStockUnits: closingStockUnits,
              currentStockValuationCost: r2(closingStockCost),
              currentStockValuationMrp: r2(closingStockMrp)
            },
            gstReport: {
              taxableAmount: r2(netSales - totalTaxRounded),
              taxableValue: r2(netSales - totalTaxRounded),
              cgst: gstCgst,
              sgst: gstSgst,
              totalTax: totalTaxRounded,
              totalGst: totalTaxRounded,
              slabs: gstSlabs
            },
            complimentarySummary: {
              billsCount: complimentaryBills.length,
              dispenseCount: complimentaryBills.length,
              unitsDispensed: totalComplimentaryUnits,
              totalUnits: totalComplimentaryUnits,
              absorbedCost: 0, // Statutory requirement: Complimentary stock cost is 0 rs
              totalCostAbsorbed: 0,
              complimentaryAbsorbedCost: 0,
              mrpValue: Number(complimentaryMrpValue.toFixed(2))
            },
            paymentBreakdown,
            modeA,
            modeB,
            topProducts: Object.values(productsMap).sort((a, b) => b.quantity - a.quantity),
            allBills: billsList,
            inwardRecords: inwardList
          };
        };

        if (reportType === 'daily') {
          const dateStr = params.get('date') || new Date().toISOString().split('T')[0];
          const dayBills = bills.filter((b: any) => (b.date || '').startsWith(dateStr));
          const stats = computeMockStats(dayBills, dateStr, dateStr, `Daily Report - ${dateStr}`);
          return makeResponse(stats);
        }

        if (reportType === 'weekly') {
          const dateStr = params.get('date') || new Date().toISOString().split('T')[0];
          const { monday, sunday } = getMondayAndSunday(dateStr);
          const weekBills = bills.filter((b: any) => b.date >= monday && b.date <= sunday);
          const stats = computeMockStats(weekBills, monday, sunday, `Weekly Report (${monday} to ${sunday})`);

          const dailyBreakdownMap: { [key: string]: { date: string; amount: number; bills: number } } = {};
          let runner = new Date(monday);
          for (let i = 0; i < 7; i++) {
            const dStr = runner.toISOString().split('T')[0];
            dailyBreakdownMap[dStr] = { date: dStr, amount: 0, bills: 0 };
            runner.setDate(runner.getDate() + 1);
          }

          weekBills.forEach((b: any) => {
            if (b.status !== 'Cancelled' && dailyBreakdownMap[b.date]) {
              dailyBreakdownMap[b.date].amount += Number(b.grand_total || 0);
              dailyBreakdownMap[b.date].bills += 1;
            }
          });

          return makeResponse({
            ...stats,
            dateRange: `${monday} to ${sunday}`,
            dailyBreakdown: Object.values(dailyBreakdownMap)
          });
        }

        if (reportType === 'monthly') {
          const monthParam = params.get('month') || (params.get('date') && params.get('date')!.substring(0, 7)) || new Date().toISOString().substring(0, 7);
          const [yearStr, mStr] = monthParam.split('-');
          const year = Number(yearStr);
          const month = Number(mStr);
          const startDate = `${monthParam}-01`;
          const lastDay = new Date(year, month, 0).getDate();
          const endDate = `${monthParam}-${String(lastDay).padStart(2, '0')}`;

          const monthBills = bills.filter((b: any) => (b.date || '').startsWith(monthParam));
          const stats = computeMockStats(monthBills, startDate, endDate, `Monthly Report - ${monthParam}`);

          const dailyTrendMap: Record<string, { date: string; amount: number; bills: number }> = {};
          for (let d = 1; d <= lastDay; d++) {
            const dStr = `${monthParam}-${String(d).padStart(2, '0')}`;
            dailyTrendMap[dStr] = { date: dStr, amount: 0, bills: 0 };
          }

          monthBills.forEach((b: any) => {
            if (b.status !== 'Cancelled' && dailyTrendMap[b.date]) {
              dailyTrendMap[b.date].amount += Number(b.grand_total || 0);
              dailyTrendMap[b.date].bills += 1;
            }
          });

          return makeResponse({
            ...stats,
            month: monthParam,
            dailyBreakdown: Object.values(dailyTrendMap)
          });
        }

        if (reportType === 'yearly') {
          const year = Number(params.get('year') || new Date().getFullYear());
          const yearBills = bills.filter((b: any) => (b.date || '').startsWith(`${year}-`));
          const stats = computeMockStats(yearBills, `${year}-01-01`, `${year}-12-31`, `Annual Report - ${year}`);

          const months = [
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
          ];
          const monthlyBreakdown = months.map((name, idx) => ({
            monthIdx: idx,
            monthName: name,
            amount: 0,
            bills: 0,
            growthPercent: 0
          }));

          yearBills.forEach((b: any) => {
            if (b.status !== 'Cancelled') {
              const mIdx = new Date(b.date).getMonth();
              if (mIdx >= 0 && mIdx < 12) {
                monthlyBreakdown[mIdx].amount += Number(b.grand_total || 0);
                monthlyBreakdown[mIdx].bills += 1;
              }
            }
          });

          for (let i = 1; i < 12; i++) {
            const prev = monthlyBreakdown[i - 1].amount;
            const curr = monthlyBreakdown[i].amount;
            monthlyBreakdown[i].growthPercent = prev === 0 ? (curr > 0 ? 1 : 0) : (curr - prev) / prev;
          }

          return makeResponse({
            ...stats,
            year,
            monthlyBreakdown
          });
        }
      }

      // ----------------------------------------------------
      // STATUTORY REGISTERS & COMPLIANCE (MOCK / OFFLINE)
      // ----------------------------------------------------
      if (path === '/api/registers/schedule-h1') {
        const registers = getDbData('schedule_h1_register', []);
        return makeResponse(registers);
      }

      if (path === '/api/registers/cold-chain') {
        let logs = getDbData('cold_chain_logs', [
          { id: 1, equipment_name: 'Vaccine & Biologics Refrigerator A', recorded_temp: 4.2, min_temp: 2.0, max_temp: 8.0, unit: 'C', status: 'NORMAL', recorded_by: 'Priya Nair, B.Pharm', recorded_at: new Date().toISOString() }
        ]);
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const temp = Number(body.recorded_temp || 4.0);
          const isExcursion = temp < 2.0 || temp > 8.0;
          const newEntry = {
            id: logs.length + 1,
            equipment_name: body.equipment_name || 'Vaccine Refrigerator A',
            recorded_temp: temp,
            min_temp: 2.0,
            max_temp: 8.0,
            unit: 'C',
            status: isExcursion ? 'EXCURSION' : 'NORMAL',
            recorded_by: body.recorded_by || 'Pharmacist',
            recorded_at: new Date().toISOString()
          };
          logs.unshift(newEntry);
          saveDbData('cold_chain_logs', logs);
          return makeResponse(newEntry, 201);
        }
        return makeResponse(logs);
      }

      if (path === '/api/registers/licences') {
        return makeResponse([
          { id: 1, licence_number: '20B/TN/CHE/00482', licence_type: 'Form 20B (Allopathic Retail)', issuing_authority: 'Drugs Control Department, Tamil Nadu', validity_start: '2023-01-01', validity_end: '2028-12-31', status: 'Active' },
          { id: 2, licence_number: '21B/TN/CHE/00482', licence_type: 'Form 21B (Schedule C & C1)', issuing_authority: 'Drugs Control Department, Tamil Nadu', validity_start: '2023-01-01', validity_end: '2028-12-31', status: 'Active' }
        ]);
      }

      if (path === '/api/audit-logs') {
        const audit = getDbData('audit_logs', []);
        return makeResponse(audit);
      }

      if (path === '/api/registers/recalls') {
        const recalled = getDbData('quarantined_batches', [
          {
            id: 1,
            batch_number: 'TRM2026A',
            product_id: 1,
            product_name: 'Voveran 50mg Tablets (15s)',
            status: 'Quarantined',
            quarantine_reason: 'CDSCO Quality Alert: Substandard dissolution rate',
            quarantined_at: new Date().toISOString()
          }
        ]);
        return makeResponse(recalled);
      }

      if (path === '/api/registers/recalls/quarantine' && method === 'POST') {
        const body = JSON.parse(init?.body as string || '{}');
        const recalled = getDbData('quarantined_batches', []);
        const newEntry = {
          id: recalled.length + 1,
          batch_number: body.batch_number,
          product_name: body.product_name || 'Quarantined Medicine',
          status: body.status || 'Quarantined',
          quarantine_reason: body.reason || 'Statutory batch hold',
          quarantined_at: new Date().toISOString(),
          authorized_by: body.authorized_by || 'Pharmacist'
        };
        recalled.unshift(newEntry);
        saveDbData('quarantined_batches', recalled);
        return makeResponse({ success: true, entry: newEntry });
      }

      if (path.startsWith('/api/registers/recalls/trace/')) {
        const batchNo = decodeURIComponent(path.replace('/api/registers/recalls/trace/', ''));
        const bills = getDbData('bills', []);
        const matched: any[] = [];
        bills.forEach((b: any) => {
          if (b.items && Array.isArray(b.items)) {
            const hasBatch = b.items.some((it: any) => (it.batch_number || '').trim().toLowerCase() === batchNo.trim().toLowerCase());
            if (hasBatch) {
              matched.push({
                bill_id: b.id,
                bill_number: b.bill_number,
                dispense_date: b.date,
                patient_name: b.patient_name || 'OP Patient',
                patient_phone: b.patient_phone || '+91 98401 XXXXX',
                patient_address: b.patient_address || 'Chennai',
                doctor_name: b.doctor_name || 'Dr. Arjun Sharma'
              });
            }
          }
        });
        return makeResponse(matched);
      }

      if (path === '/api/registers/adr-reports') {
        const adrs = getDbData('adr_reports', [
          {
            id: 1,
            report_date: new Date().toISOString().split('T')[0],
            patient_name: 'S. Ramanathan',
            patient_age: 52,
            patient_gender: 'Male',
            suspected_drug: 'Dynapar AQ 75mg/1mL Injection',
            generic_name: 'Diclofenac Sodium IP 75mg/1mL',
            batch_number: 'DYN-7812',
            reaction_description: 'Transient localized erythema and mild urticarial rash 20 minutes post-IM injection.',
            reaction_date: new Date().toISOString().split('T')[0],
            severity: 'MILD',
            outcome: 'RECOVERED',
            reported_by: 'Priya Nair, B.Pharm',
            reporter_qualification: 'Registered Pharmacist'
          }
        ]);
        if (method === 'POST') {
          const body = JSON.parse(init?.body as string || '{}');
          const newReport = {
            id: adrs.length + 1,
            report_date: new Date().toISOString().split('T')[0],
            patient_name: body.patient_name || 'Patient',
            patient_age: Number(body.patient_age) || null,
            patient_gender: body.patient_gender || null,
            suspected_drug: body.suspected_drug || 'Unknown',
            generic_name: body.generic_name || body.suspected_drug || 'Unknown',
            batch_number: body.batch_number || 'N/A',
            reaction_description: body.reaction_description || 'Adverse drug reaction reported',
            reaction_date: body.reaction_date || new Date().toISOString().split('T')[0],
            severity: body.severity || 'MODERATE',
            outcome: body.outcome || 'RECOVERING',
            reported_by: body.reported_by || 'Pharmacist',
            reporter_qualification: body.reporter_qualification || 'B.Pharm'
          };
          adrs.unshift(newReport);
          saveDbData('adr_reports', adrs);
          return makeResponse(newReport, 201);
        }
        return makeResponse(adrs);
      }

      if (path === '/api/clinical/check-interactions' && method === 'POST') {
        const body = JSON.parse(init?.body as string || '{}');
        const items = body.items || [];
        const alerts: any[] = [];
        const critical: any[] = [];
        
        // Check systemic NSAIDs duplicate
        const nsaids = items.filter((it: any) => {
          const cat = (it.category || '').toLowerCase();
          return cat === 'nsaids' || cat === 'combination analgesics';
        });
        if (nsaids.length >= 2) {
          const names = nsaids.map((n: any) => n.name).join(', ');
          alerts.push({
            severity: 'WARNING',
            title: 'Duplicate Systemic NSAIDs Prescribed',
            message: `Multiple non-steroidal anti-inflammatory formulations prescribed concurrently (${names}). Increases gastric ulceration and nephrotoxicity risk.`,
            recommendation: 'Use single systemic NSAID at lowest effective dose; add gastroprotective agent.'
          });
        }
        return makeResponse({ alerts, critical });
      }

      if (path.startsWith('/api/batches/product/')) {
        const prodId = Number(path.replace('/api/batches/product/', ''));
        return makeResponse([
          { id: prodId * 10, product_id: prodId, batch_number: 'MOC' + (1000 + prodId), expiry_date: '2027-12-31', stock: 100, status: 'Active' }
        ]);
      }

      if (path === '/api/system/clear-example-records' && method === 'POST') {
        let patients = getDbData('patients', DEFAULT_PATIENTS);
        const initPatLen = patients.length;
        patients = patients.filter((p: any) => !p.is_example);
        saveDbData('patients', patients);

        let employees = getDbData('employees', DEFAULT_EMPLOYEES);
        const initEmpLen = employees.length;
        employees = employees.filter((e: any) => !e.is_example);
        saveDbData('employees', employees);

        let bills = getDbData('bills', []);
        const initBillLen = bills.length;
        bills = bills.filter((b: any) => !b.is_example);
        saveDbData('bills', bills);

        return makeResponse({
          success: true,
          message: "All example placeholder records have been purged.",
          purged: {
            patients: initPatLen - patients.length,
            employees: initEmpLen - employees.length,
            bills: initBillLen - bills.length
          }
        });
      }

      // Safe fallback for unhandled requests: return 200 with empty object to prevent frontend crashes
      console.warn(`[MOCK DB] Unhandled offline endpoint: ${method} ${path}`);
      return makeResponse({ success: true, warning: "Offline mock: route not explicitly handled." }, 200);

    } catch (err: any) {
      console.error("[MOCK DB] Error processing request:", err);
      return makeResponse({ error: err.message }, 500);
    }
  };
}
